from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline SYR2K kernel on the lower-triangular part of C:
#   C := beta * C + alpha * A * B^T + alpha * B * A^T
@proc
def kernel_syr2k_unoptimized(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
    B: DATA_TYPE[n, m] @ DRAM,
):

    assert n >= 1
    assert m >= 1

    # Scale only the lower triangular part of C by beta.
    # This matches the PolyBench syr2k kernel semantics.
    for i in seq(0, n):
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

    # Perform the symmetric rank-2k update on the lower triangle:
    #   C[i,j] += alpha * A[i,:]·B[j,:]^T + alpha * B[i,:]·A[j,:]^T
    for i in seq(0, n):
        for k in seq(0, m):
            # Precompute the factors that are invariant across j for
            # this (i, k) pair. This improves arithmetic intensity by
            # hoisting the multiplications by alpha out of the j-loop.
            aik: DATA_TYPE
            bik: DATA_TYPE
            aik = alpha * A[i, k]
            bik = alpha * B[i, k]

            # j only runs over the lower triangle (j <= i).
            for j in seq(0, i + 1):
                C[i, j] += aik * B[j, k] + bik * A[j, k]


