# constant trip count (32); the guards produced by tail="guard" make
# out-of-range iterations no-ops.
ji_loop = p1.find_loop("ji")
p2 = unroll_loop(p1, ji_loop)

# Clean up algebra and guards after the transformations.
p3 = simplify(p2)

# Export the scheduled kernel under the name expected by the C driver.
kernel_syr2k = rename(p3, "kernel_syr2k")
