        # C[i, j] += A[j, k] * alpha * B[i, k] + B[j, k] * alpha * A[i, k]
        # for all k and for all j <= i.
        for k in seq(0, m):
            for j in seq(0, i + 1):
                C[i, j] += (
                    A[j, k] * alpha * B[i, k]
                    + B[j, k] * alpha * A[i, k]
                )

